<?php require '../config/db.php';require '../includes/functions.php';need_admin();$a=$_GET['action']??'list';$id=(int)($_GET['id']??0);$err='';if($a==='delete'&&$id){$st=$pdo->prepare('DELETE FROM fields WHERE id=?');$st->execute([$id]);header('Location: fields.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']);$d=trim($_POST['description']);if($n==='')$err='Field name is required.';else{if($id){$st=$pdo->prepare('UPDATE fields SET name=?,description=? WHERE id=?');$st->execute([$n,$d,$id]);}else{$st=$pdo->prepare('INSERT INTO fields(name,description) VALUES(?,?)');$st->execute([$n,$d]);}header('Location: fields.php');exit;}}$item=null;if($a==='edit'&&$id){$st=$pdo->prepare('SELECT * FROM fields WHERE id=?');$st->execute([$id]);$item=$st->fetch();}$title='Manage Fields';require '_header.php';?><div class="d-flex justify-content-between align-items-center mb-3"><h1>Fields</h1><a class="btn btn-primary" href="?action=add">+ Add Field</a></div><?php if($a==='add'||$a==='edit'): ?><div class="card p-4"><h4><?=$a==='edit'?'Edit':'Add'?> Field</h4><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post"><label class="form-label">Name *</label><input class="form-control mb-3" name="name" value="<?=e($item['name']??'')?>" required><label class="form-label">Description</label><textarea class="form-control" name="description"><?=e($item['description']??'')?></textarea><button class="btn btn-primary mt-4">Save</button> <a class="btn btn-outline-secondary mt-4" href="fields.php">Cancel</a></form></div><?php else: ?><div class="table-card table-responsive"><table class="table"><thead><tr><th>Field</th><th>Description</th><th>Action</th></tr></thead><tbody><?php foreach($pdo->query('SELECT * FROM fields ORDER BY id DESC') as $r): ?><tr><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><a class="btn btn-sm btn-outline-dark" href="?action=edit&id=<?=$r['id']?>">Edit</a> <a data-confirm="Delete this field?" class="btn btn-sm btn-outline-danger" href="?action=delete&id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php require '_footer.php'; ?>
